 String date(long time,String format){return new SimpleDateFormat(format,Locale.KOREA).format(new Date(time));}
 String timeRange(JSONObject m){long start=m.optLong("startedAt"),end=m.optLong("endedAt");if(end<=0)return date(start,"HH:mm")+" 시작 · "+(m.optString("status").equals("recording")?"진행 중":"일시정지");long minutes=Math.max(1,(end-start+59999)/60000);return date(start,"HH:mm")+"–"+date(end,"HH:mm")+" · "+minutes+"분";}
 String stage(JSONObject m){String a=m.optString("minutesStatus");if(a.equals("ready"))return "회의록 완료";if(a.equals("generating")||a.equals("queued"))return "회의록 만드는 중";if(a.equals("failed")||a.equals("interrupted"))return "회의록 다시 만들기";String s=m.optString("status");return s.equals("recording")?"원문 기록 중":s.equals("paused")?"잠시 멈춤":s.equals("interrupted")?"복구된 원문":"원문 저장 완료";}
 void renderRecords(){if(!archivePage||records==null)return;renderCalendar();int scroll=homeScroll.getScrollY();records.removeAllViews();String prior="";int count=0;for(int i=0;i<cache.length();i++){JSONObject m=cache.optJSONObject(i);if(m==null)continue;String day=date(m.optLong("startedAt"),"yyyy-MM-dd");if(!selectedDay.isEmpty()&&!selectedDay.equals(day))continue;if(!day.equals(prior)){gap(records,12);records.addView(text(date(m.optLong("startedAt"),"yyyy년 M월 d일 EEEE"),13,MUTED,true));gap(records,9);prior=day;}count++;LinearLayout card=column();card.setPadding(dp(18),dp(16),dp(18),dp(16));card.setBackground(shape(WHITE,20));LinearLayout row=new LinearLayout(this);TextView when=text(m.optString("title",date(m.optLong("startedAt"),"HH:mm")+" 회의"),18,INK,true);when.setMaxLines(2);row.addView(when,new LinearLayout.LayoutParams(0,-2,1));TextView badge=text(stage(m),11,INK,true);badge.setPadding(dp(9),dp(6),dp(9),dp(6));badge.setBackground(shape(m.optString("minutesStatus").equals("ready")?GREEN:BG,10));row.addView(badge);card.addView(row);gap(card,8);card.addView(text(timeRange(m)+"  ·  "+m.optInt("segments")+"개 발언",12,MUTED,false));if(!m.optString("searchSnippet").isEmpty()){gap(card,8);card.addView(text(m.optString("searchKind")+" · "+m.optString("searchSnippet"),12,INK,false));}if(!m.optString("minutesProgress").isEmpty()&&!m.optString("minutesStatus").equals("ready")){gap(card,4);card.addView(text(m.optString("minutesProgress"),11,MUTED,false));}String id=m.optString("id");int resultTab=m.optInt("searchTab",0);SwipeMeetingCard swipe=new SwipeMeetingCard(this,card,()->detail(id,resultTab),()->confirmDelete(id),()->shareMeeting(id));swipe.bind(()->confirmDelete(id),()->shareMeeting(id));records.addView(swipe,new LinearLayout.LayoutParams(-1,-2));gap(records,9);}if(count==0){TextView empty=text(searchQuery.isEmpty()?"아직 저장된 회의가 없습니다.\n대화 자막을 시작하면 여기에 기록됩니다.":"검색 결과가 없습니다.\n다른 단어나 띄어쓰기로 검색해 보세요.",15,MUTED,false);empty.setPadding(dp(12),dp(32),dp(12),dp(32));records.addView(empty);}stats.setText((selectedDay.isEmpty()?"회의 기록":selectedDay)+"  "+count);homeScroll.post(()->{if(meetingSearch!=null&&meetingSearch.hasFocus())revealSearch();else homeScroll.scrollTo(0,scroll);});}
 // Keep the focused field visible after IME resizing and asynchronous result relayout.
 void revealSearch(){if(detailId!=null||homeScroll==null||meetingSearch==null||!meetingSearch.hasFocus()||!meetingSearch.isAttachedToWindow())return;android.graphics.Rect area=new android.graphics.Rect();meetingSearch.getDrawingRect(area);area.top-=dp(12);area.bottom+=dp(12);meetingSearch.requestRectangleOnScreen(area,true);}
 void renderCalendar(){if(calendarHost==null)return;calendarHost.removeAllViews();LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER_VERTICAL);nav.addView(button("‹",false,()->{calendarMonth.add(Calendar.MONTH,-1);renderCalendar();}),new LinearLayout.LayoutParams(dp(48),dp(44)));TextView month=text(date(calendarMonth.getTimeInMillis(),"yyyy년 M월"),19,INK,true);month.setGravity(Gravity.CENTER);nav.addView(month,new LinearLayout.LayoutParams(0,dp(44),1));nav.addView(button("›",false,()->{calendarMonth.add(Calendar.MONTH,1);renderCalendar();}),new LinearLayout.LayoutParams(dp(48),dp(44)));calendarHost.addView(nav);Calendar day=(Calendar)calendarMonth.clone();day.set(Calendar.DAY_OF_MONTH,1);int blank=day.get(Calendar.DAY_OF_WEEK)-1,total=day.getActualMaximum(Calendar.DAY_OF_MONTH);String[] weekdays={"일","월","화","수","목","금","토"};LinearLayout labels=new LinearLayout(this);for(String w:weekdays){TextView label=text(w,11,MUTED,true);label.setGravity(Gravity.CENTER);labels.addView(label,new LinearLayout.LayoutParams(0,dp(28),1));}calendarHost.addView(labels);for(int row=0;row<(blank+total+6)/7;row++){LinearLayout week=new LinearLayout(this);for(int col=0;col<7;col++){int number=row*7+col-blank+1;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);if(number>=1&&number<=total){day.set(Calendar.DAY_OF_MONTH,number);String key=date(day.getTimeInMillis(),"yyyy-MM-dd");int amount=0;for(int i=0;i<calendarItems.length();i++){JSONObject m=calendarItems.optJSONObject(i);if(m!=null&&key.equals(date(m.optLong("startedAt"),"yyyy-MM-dd")))amount++;}TextView label=text(""+number,14,INK,true);cell.addView(label);if(amount>0){TextView badge=text("▤ "+amount,10,INK,true);badge.setPadding(dp(5),0,dp(5),0);badge.setBackground(shape(GREEN,8));cell.addView(badge);}if(key.equals(selectedDay))cell.setBackground(shape(0xffe5e5e5,10));cell.setContentDescription(key+" 회의 "+amount+"개");cell.setOnClickListener(v->{selectedDay=key;searchQuery="";if(meetingSearch!=null){meetingSearch.setText("");meetingSearch.clearFocus();}lastList="";refresh();});}week.addView(cell,new LinearLayout.LayoutParams(0,dp(57),1));}calendarHost.addView(week);}}
 void confirmDelete(String id){new AlertDialog.Builder(this).setTitle("회의 기록을 삭제할까요?").setMessage("자막 원문과 AI 회의록을 함께 삭제합니다. 되돌릴 수 없습니다.").setPositiveButton("삭제",(d,w)->new Thread(()->{try{MeetingManager.get(this).deleteMeeting(id);runOnUiThread(()->{lastList="";refresh();toast("회의 기록을 삭제했습니다");});}catch(Exception e){runOnUiThread(()->toast(e.getCause()==null?e.getMessage():e.getCause().getMessage()));}},"meeting-delete").start()).setNegativeButton("취소",null).show();}
 void shareMeeting(String id){new Thread(()->{try{MeetingManager manager=MeetingManager.get(this);JSONObject meta=manager.store.meta(id);String raw;try{raw=MeetingStore.read(manager.document(id,"minutes"));}catch(Exception absent){raw=MeetingStore.read(manager.document(id,"transcript"));}File folder=new File(getCacheDir(),"shares");folder.mkdirs();File file=new File(folder,"meeting-"+id+".html");MeetingStore.atomic(file,MinutesDocument.html(meta.optString("title"),date(meta.optLong("startedAt"),"yyyy.MM.dd")+" · "+timeRange(meta),raw));android.net.Uri uri=android.net.Uri.parse("content://com.mcnex.conversation.meetings/"+file.getName());runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_SEND).setType("text/html").putExtra(Intent.EXTRA_SUBJECT,meta.optString("title")).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("회의록",uri));startActivity(Intent.createChooser(intent,"회의록 문서 공유"));});}catch(Exception e){runOnUiThread(()->toast("공유 실패: "+e.getMessage()));}},"meeting-share").start();}

 void detail(String id,int tab){settingsPage=false;archivePage=false;phonePage=false;detailId=id;detailTab=tab;screen();Button back=button("‹  회의 기록",false,this::archive);root.addView(back);gap(root,16);JSONObject meta=null;for(int i=0;i<cache.length();i++)if(id.equals(cache.optJSONObject(i).optString("id")))meta=cache.optJSONObject(i);root.addView(text(meta==null?"회의 기록":meta.optString("title",date(meta.optLong("startedAt"),"M월 d일 HH:mm 회의")),25,INK,true));gap(root,8);detailStatus=text(meta==null?"":date(meta.optLong("startedAt"),"yyyy.MM.dd ")+timeRange(meta)+"\n"+stage(meta),12,MUTED,false);root.addView(detailStatus);gap(root,18);LinearLayout tabs=new LinearLayout(this);for(int i=0;i<2;i++){final int chosen=i;Button b=button(i==0?"자막 원문":"AI 회의록",i==tab,()->switchDetail(chosen));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);if(i==1)lp.leftMargin=dp(8);tabs.addView(b,lp);}root.addView(tabs);gap(root,12);ScrollView scroll=new ScrollView(this);document=text("불러오는 중…",15,INK,false);document.setTextIsSelectable(true);document.setPadding(dp(18),dp(18),dp(18),dp(18));document.setBackground(shape(WHITE,20));if(tab==1){minutesHost=null;minutesWeb=minutesBrowser();root.addView(minutesWeb,new LinearLayout.LayoutParams(-1,0,1));}else{minutesHost=null;minutesWeb=null;scroll.addView(document);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}gap(root,8);LinearLayout readerTools=new LinearLayout(this);if(tab==1){readerTools.addView(button("전체 화면 · 확대",false,this::fullMinutes),new LinearLayout.LayoutParams(0,dp(44),1));Button more=button("문서 메뉴  ⋯",true,()->documentMenu(id));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(44),1);lp.leftMargin=dp(8);readerTools.addView(more,lp);}else readerTools.addView(button("원문 TXT 저장",true,()->export(id,"transcript")),new LinearLayout.LayoutParams(-1,dp(44)));root.addView(readerTools);loadDocument(id,tab);}
 void documentMenu(String id){new AlertDialog.Builder(this).setTitle("회의록 문서").setItems(new String[]{"양식 문서 저장 (HTML)","PDF 저장 · 인쇄","회의록 TXT 저장","회의록 생성 / 다시 생성"},(d,index)->{if(index==0)export(id,"html");else if(index==1)printMinutes();else if(index==2)export(id,"minutes");else new Thread(()->{try{MeetingManager.get(this).generate(id);runOnUiThread(()->toast("회의록 생성을 시작했습니다"));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}},"minutes-start").start();}).setNegativeButton("닫기",null).show();}
 void switchDetail(int tab){if(navAnimating||detailId==null)return;if(tab<0||tab>1||tab==detailTab){root.animate().translationX(0).setDuration(180).start();return;}String id=detailId;View old=root;int width=old.getWidth(),height=old.getHeight(),direction=tab>detailTab?1:-1;float offset=old.getTranslationX();if(width<=0||height<=0||!android.animation.ValueAnimator.areAnimatorsEnabled()){detail(id,tab);return;}android.graphics.Bitmap bitmap;try{bitmap=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);old.draw(new android.graphics.Canvas(bitmap));}catch(OutOfMemoryError noSnapshot){detail(id,tab);return;}navAnimating=true;detail(id,tab);android.widget.FrameLayout content=findViewById(android.R.id.content);ImageView overlay=new ImageView(this);overlay.setImageBitmap(bitmap);overlay.setScaleType(ImageView.ScaleType.FIT_XY);content.addView(overlay,new android.widget.FrameLayout.LayoutParams(width,height));overlay.setTranslationX(offset);root.setTranslationX(direction*width+offset);android.view.animation.Interpolator curve=new android.view.animation.PathInterpolator(.22f,.8f,.2f,1f);root.animate().translationX(0).setDuration(300).setInterpolator(curve).start();overlay.animate().translationX(-direction*width).setDuration(300).setInterpolator(curve).withEndAction(()->{content.removeView(overlay);overlay.setImageDrawable(null);bitmap.recycle();navAnimating=false;}).start();}
 boolean dispatchDetailSwipe(MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){navX=event.getRawX();navY=event.getRawY();navDragging=false;navBlocked=false;}if(event.getPointerCount()>1)navBlocked=true;if(action==MotionEvent.ACTION_MOVE&&!navBlocked&&Math.abs(event.getRawX()-navX)>dp(65)&&Math.abs(event.getRawX()-navX)>Math.abs(event.getRawY()-navY)*1.8){if(!navDragging){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();navDragging=true;}root.setTranslationX(Math.max(-root.getWidth()*.6f,Math.min(root.getWidth()*.6f,(event.getRawX()-navX)*.65f)));return true;}if(action==MotionEvent.ACTION_UP&&navDragging){int target=detailTab+(event.getRawX()<navX?1:-1);navDragging=false;switchDetail(target);return true;}if(action==MotionEvent.ACTION_CANCEL){navDragging=false;root.animate().translationX(0).setDuration(180).start();}return super.dispatchTouchEvent(event);}
 void showDetailText(String shown,int tab){loadedDocument=shown;if(tab==1&&minutesWeb!=null)minutesWeb.loadDataWithBaseURL(null,minutesHtml(),"text/html","UTF-8",null);else document.setText(shown);}
 void loadDocument(String id,int tab){String remembered=detailDocuments.get(id+":"+tab);if(remembered!=null)showDetailText(remembered,tab);new Thread(()->{String value;try{File file=MeetingManager.get(this).document(id,tab==0?"transcript":"minutes");StringBuilder out=new StringBuilder();try(Reader in=new InputStreamReader(new FileInputStream(file),StandardCharsets.UTF_8)){char[] b=new char[4096];int n;while((n=in.read(b))!=-1){out.append(b,0,n);if(out.length()>200000){out.append("\n[화면 미리보기 · TXT 저장 시 전체 내용이 저장됩니다]");break;}}}value=out.toString();}catch(Exception e){value=tab==1?"아직 회의록이 없습니다.\n회의 완료 후 ‘회의록 생성’을 눌러주세요.\n\n원문은 별도 탭에 보존되어 있습니다.":"자막 원문이 저장되면 여기에 표시됩니다.";}String shown=value;runOnUiThread(()->{if(id.equals(detailId)&&tab==detailTab){if(detailDocuments.size()>=4&&!detailDocuments.containsKey(id+":"+tab))detailDocuments.clear();detailDocuments.put(id+":"+tab,shown);showDetailText(shown,tab);}});},"meeting-read").start();}
 String minutesHtml(){JSONObject meta=null;for(int i=0;i<cache.length();i++){JSONObject m=cache.optJSONObject(i);if(m!=null&&m.optString("id").equals(detailId)){meta=m;break;}}return MinutesDocument.html(meta==null?"AI 회의록":meta.optString("title","AI 회의록"),meta==null?"":date(meta.optLong("startedAt"),"yyyy년 M월 d일")+"  ·  "+timeRange(meta),loadedDocument);}
 android.webkit.WebView minutesBrowser(){android.webkit.WebView view=new android.webkit.WebView(this);view.setBackgroundColor(BG);view.getSettings().setJavaScriptEnabled(false);view.getSettings().setAllowFileAccess(false);view.getSettings().setAllowContentAccess(false);view.getSettings().setBuiltInZoomControls(true);view.getSettings().setDisplayZoomControls(false);view.getSettings().setTextZoom(readingSize*100/16);view.setWebViewClient(new android.webkit.WebViewClient(){@Override public boolean shouldOverrideUrlLoading(android.webkit.WebView v,android.webkit.WebResourceRequest r){return true;}});return view;}
 void printMinutes(){if(minutesWeb==null||loadedDocument.isEmpty()){toast("회의록을 먼저 불러오세요");return;}android.print.PrintManager manager=(android.print.PrintManager)getSystemService(PRINT_SERVICE);manager.print("Memo 회의록",minutesWeb.createPrintDocumentAdapter("Memo 회의록"),new android.print.PrintAttributes.Builder().setMediaSize(android.print.PrintAttributes.MediaSize.ISO_A4).build());}
 void fullMinutes(){Dialog dialog=new Dialog(this,android.R.style.Theme_Material_Light_NoActionBar);LinearLayout page=column();page.setBackgroundColor(BG);LinearLayout tools=new LinearLayout(this);tools.addView(button("닫기",false,dialog::dismiss),new LinearLayout.LayoutParams(0,dp(48),1));android.webkit.WebView web=minutesBrowser();for(int delta:new int[]{-2,2}){Button zoom=button(delta<0?"A−":"A＋",false,()->{readingSize=Math.max(12,Math.min(30,readingSize+delta));web.getSettings().setTextZoom(readingSize*100/16);});tools.addView(zoom,new LinearLayout.LayoutParams(dp(68),dp(48)));}page.addView(tools);page.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.loadDataWithBaseURL(null,minutesHtml(),"text/html","UTF-8",null);dialog.setContentView(page);dialog.show();dialog.getWindow().setLayout(-1,-1);page.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(8),bars.top+dp(8),dp(8),bars.bottom+dp(8));return insets;});page.requestApplyInsets();dialog.setOnDismissListener(d->{if(minutesWeb!=null)minutesWeb.getSettings().setTextZoom(readingSize*100/16);web.destroy();});}
 CharSequence formatted(String value){android.text.SpannableStringBuilder out=new android.text.SpannableStringBuilder();for(String line:value.split("\n",-1)){int start=out.length();boolean heading=line.startsWith("#")||line.startsWith("===")||(line.startsWith("**")&&line.endsWith("**"))||line.startsWith("회의록 —");String clean=line.replaceAll("^#{1,6}\\s+","").replace("**","").replaceAll("^\\*\\s+","• ").replace("===","").trim();out.append(clean).append("\n");if(heading&&out.length()>start){out.setSpan(new android.text.style.StyleSpan(Typeface.BOLD),start,out.length(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);out.setSpan(new android.text.style.RelativeSizeSpan(1.1f),start,out.length(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}return out;}
 void refresh(){if(settingsPage)return;if(phonePage){refreshPhone();return;}if(loading)return;loading=true;new Thread(()->{try{String query=searchQuery;JSONArray allMeetings=MeetingManager.get(this).list();JSONArray list=query.trim().isEmpty()?allMeetings:MeetingManager.get(this).search(query);String state=MeetingManager.get(this).stateText();runOnUiThread(()->{if(!query.equals(searchQuery))return;cache=list;calendarItems=allMeetings;if(overview!=null&&archivePage)overview.setText("현재 "+date(System.currentTimeMillis(),"yyyy년 M월 d일")+"  ·  총 "+allMeetings.length()+"건");if(detailId==null){if(status!=null)status.setText(state.isEmpty()?(AssistService.running?"연결 준비 완료 · MemoMind에서 자막 시작":"자동 연결을 시작하세요"):state);String signature=selectedDay+searchQuery+list.toString()+(archivePage?allMeetings.toString():"");if(!signature.equals(lastList)){lastList=signature;renderRecords();}}else{for(int i=0;i<list.length();i++){JSONObject m=list.optJSONObject(i);if(detailId.equals(m.optString("id"))){String text=date(m.optLong("startedAt"),"yyyy.MM.dd ")+timeRange(m)+"\n"+stage(m)+"  "+m.optString("minutesProgress");if(!text.contentEquals(detailStatus.getText())){detailStatus.setText(text);loadDocument(detailId,detailTab);}break;}}}});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}finally{loading=false;}},"meeting-refresh").start();}
 void phoneMeeting(){currentTab=1;settingsPage=false;archivePage=false;phonePage=true;detailId=null;screen();pageHeader(1);root.addView(text("휴대폰 회의",28,INK,true));root.addView(text("MemoMind·안경 없이 휴대폰 마이크로 기록합니다.",12,MUTED,false));gap(root,14);phoneState=text("듣기 시작을 눌러주세요",14,INK,true);root.addView(phoneState);gap(root,12);ScrollView captions=new ScrollView(this);phoneCaption=text("대화 자막이 여기에 표시됩니다.",14,MUTED,false);phoneCaption.setTextIsSelectable(true);phoneCaption.setPadding(dp(16),dp(16),dp(16),dp(16));phoneCaption.setBackground(shape(WHITE,18));captions.addView(phoneCaption);root.addView(captions,new LinearLayout.LayoutParams(-1,0,1));gap(root,10);root.addView(text("AI Tip",12,MUTED,true));phoneTip=text("질문·어려운 용어가 있으면 로컬 AI가 도움을 제안합니다.",14,MUTED,false);phoneTip.setPadding(dp(14),dp(12),dp(14),dp(12));phoneTip.setBackground(shape(WHITE,16));phoneTip.setMaxLines(3);phoneTip.setEllipsize(android.text.TextUtils.TruncateAt.END);phoneTip.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("AI Tip").setMessage(phoneTip.getText()).setPositiveButton("확인",null).show());root.addView(phoneTip,new LinearLayout.LayoutParams(-1,dp(94)));gap(root,12);LinearLayout controls=new LinearLayout(this);controls.addView(button("듣기 시작 / 재개",true,()->phoneAction("phone-start")),new LinearLayout.LayoutParams(0,dp(52),1));controls.addView(button("일시정지",false,()->phoneAction("phone-pause")),new LinearLayout.LayoutParams(0,dp(52),1));root.addView(controls);gap(root,8);root.addView(button("회의 완료 · 회의록 생성",true,()->new AlertDialog.Builder(this).setTitle("회의를 완료할까요?").setMessage("원문 전체를 저장하고 선택한 로컬 AI로 회의록을 만듭니다.").setPositiveButton("완료",(d,w)->completeMeeting()).setNegativeButton("취소",null).show()),new LinearLayout.LayoutParams(-1,dp(52)));refreshPhone();}
 void phoneAction(String action){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=0){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},21);toast("마이크 권한 허용 후 다시 시작하세요");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);phoneState.setText(action.equals("phone-start")?"휴대폰 마이크 준비 중…":"일시정지 중…");startForegroundService(new Intent(this,AssistService.class).setAction(action));}
 void resetPhoneMeetingDisplay(){phoneHelpGeneration++;phoneHelpContext="";phoneHelpSession="";phoneHelpAt=0;phoneTopics.clear();if(phoneCaption!=null){phoneCaption.setTextColor(MUTED);phoneCaption.setText("대화 자막이 여기에 표시됩니다.");}if(phoneTip!=null){phoneTip.setTextColor(MUTED);phoneTip.setText("질문·어려운 용어가 있으면 로컬 AI가 도움을 제안합니다.");}}
 void refreshPhone(){if(!phonePage||phoneState==null)return;AssistService service=AssistService.current;if(service==null){phoneState.setText("듣기 시작을 눌러주세요");return;}try{JSONObject snap=service.phoneSnapshot();JSONObject active=snap.optJSONObject("meeting");if(active!=null&&active.optString("activeId").isEmpty()){resetPhoneMeetingDisplay();phoneState.setText("새 회의 · 듣기 시작을 눌러주세요"+(active.optString("progress").isEmpty()?"":"\n"+active.optString("progress")));return;}String error=snap.optString("phoneError");if(error.isEmpty())error=snap.optString("error");phoneState.setText(!error.isEmpty()?error:snap.optBoolean("phoneRecording")?"● 휴대폰 마이크 · 원문 저장 중":"일시정지 · 저장된 회의에 이어 기록 가능");StringBuilder text=new StringBuilder(),context=new StringBuilder();JSONArray finals=snap.optJSONArray("finals");String partial=snap.optString("partial");if(!partial.isEmpty())text.append(partial).append("\n\n");if(finals!=null){for(int i=finals.length()-1;i>=Math.max(0,finals.length()-8);i--)text.append(finals.optJSONObject(i).optString("text")).append("\n\n");for(int i=Math.max(0,finals.length()-8);i<finals.length();i++)context.append(finals.optJSONObject(i).optString("text")).append("\n");}context.append(partial);if(text.length()>0){phoneCaption.setTextColor(INK);phoneCaption.setText(text);}if(snap.optBoolean("phoneRecording"))phoneHelp(snap,context.toString());JSONObject meeting=snap.optJSONObject("meeting");if(meeting!=null&&!meeting.optString("progress").isEmpty())phoneState.append("\n"+meeting.optString("progress"));}catch(Exception e){phoneState.setText(e.getMessage());}}
 void startConnection(){if(copying){toast("모델을 가져오는 중입니다");return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=0){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},21);toast("안경 음성인식을 허용한 뒤 다시 시작하세요");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);AssistService.PAIRING.open(System.currentTimeMillis());startForegroundService(new Intent(this,AssistService.class));toast("자동 연결을 시작했습니다. MemoMind 폰 플러그인을 실행하세요.");}
 void pageHeader(int selected){TextView brand=text("MEMO / MEETING",13,INK,true);brand.setLetterSpacing(.05f);root.addView(brand);gap(root,14);LinearLayout tabs=new LinearLayout(this);String[] labels={"회의록","휴대폰 회의","설정"};for(int i=0;i<3;i++){final int index=i;Button tab=button(labels[i],selected==i,()->navigate(index));tab.setTextSize(13);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);if(i>0)lp.leftMargin=dp(6);tabs.addView(tab,lp);}root.addView(tabs);gap(root,10);View rule=new View(this);rule.setBackgroundColor(0xffe7e7e7);root.addView(rule,new LinearLayout.LayoutParams(-1,dp(1)));gap(root,20);}
 void buildTab(int tab){if(tab==0)archive();else if(tab==1)phoneMeeting();else settings();}
 void navigate(int tab){navigate(tab,0);}
 void navigate(int tab,int swipeDirection){if(navAnimating)return;if(tab<0||tab>2){root.animate().translationX(0).setDuration(180).start();return;}if(tab==currentTab&&detailId==null){root.animate().translationX(0).setDuration(180).start();return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);View outgoing=root;int previous=currentTab,width=outgoing.getWidth(),height=outgoing.getHeight();float offset=outgoing.getTranslationX();if(width<=0||height<=0||!android.animation.ValueAnimator.areAnimatorsEnabled()){buildTab(tab);return;}android.graphics.Bitmap bitmap;try{bitmap=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);outgoing.draw(new android.graphics.Canvas(bitmap));}catch(OutOfMemoryError noSnapshot){buildTab(tab);return;}navAnimating=true;buildTab(tab);View incoming=root;android.widget.FrameLayout container=(android.widget.FrameLayout)findViewById(android.R.id.content);ImageView previousPage=new ImageView(this);previousPage.setImageBitmap(bitmap);previousPage.setScaleType(ImageView.ScaleType.FIT_XY);container.addView(previousPage,new android.widget.FrameLayout.LayoutParams(width,height));previousPage.setTranslationX(offset);int direction=swipeDirection!=0?swipeDirection:tab>previous?1:-1;incoming.setTranslationX(direction*width+offset);incoming.setAlpha(1f);android.view.animation.Interpolator curve=new android.view.animation.PathInterpolator(.22f,.8f,.2f,1f);incoming.animate().translationX(0).setDuration(300).setInterpolator(curve).start();previousPage.animate().translationX(-direction*width).setDuration(300).setInterpolator(curve).withEndAction(()->{container.removeView(previousPage);previousPage.setImageDrawable(null);bitmap.recycle();navAnimating=false;}).start();}
 boolean blocksNavigation(View view,float x,float y){android.graphics.Rect rect=new android.graphics.Rect();if(!view.getGlobalVisibleRect(rect)||!rect.contains((int)x,(int)y))return false;if(view instanceof SwipeMeetingCard||view instanceof EditText||view instanceof android.webkit.WebView)return true;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=group.getChildCount()-1;i>=0;i--)if(blocksNavigation(group.getChildAt(i),x,y))return true;}return false;}
 @Override public boolean dispatchTouchEvent(MotionEvent event){if(navAnimating)return true;if(detailId!=null)return dispatchDetailSwipe(event);int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){navX=event.getRawX();navY=event.getRawY();navBlocked=blocksNavigation(root,navX,navY);navDragging=false;}else if(action==MotionEvent.ACTION_MOVE&&!navBlocked&&event.getPointerCount()==1&&Math.abs(event.getRawX()-navX)>dp(65)&&Math.abs(event.getRawX()-navX)>Math.abs(event.getRawY()-navY)*1.8){if(!navDragging){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();navDragging=true;}float drag=event.getRawX()-navX;root.setTranslationX(Math.max(-root.getWidth()*.6f,Math.min(root.getWidth()*.6f,drag*.65f)));return true;}else if(action==MotionEvent.ACTION_UP&&navDragging){int direction=event.getRawX()<navX?1:-1;int target=Math.floorMod(currentTab+direction,3);navDragging=false;navigate(target,direction);return true;}else if(action==MotionEvent.ACTION_CANCEL){navDragging=false;root.animate().translationX(0).setDuration(180).start();}return super.dispatchTouchEvent(event);}
