 void settings(){currentTab=2;settingsPage=true;phonePage=false;archivePage=false;detailId=null;screen();pageHeader(2);root.addView(text("회의록 설정",27,INK,true));root.addView(text("각 기능의 동작과 로컬 AI 설정을 관리합니다.",12,MUTED,false));gap(root,14);ScrollView scroll=new ScrollView(this);LinearLayout content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));MeetingManager m=MeetingManager.get(this);kakaoSettings(content);settingItem(content,"AI 모델 관리","현재 선택: "+m.modelName()+"\n.litertlm과 GGUF 모델을 등록·선택하고 같은 질문으로 속도를 시험합니다. 모델은 한 번에 하나만 실행합니다.","모델 등록 · 선택 · 테스트",this::modelSettings);settingItem(content,"GGUF CPU / GPU","현재: "+m.ggufBackend()+"\nEXAONE 등 GGUF의 연산 장치를 바꿉니다. Adreno GPU는 첫 준비 시간이 길 수 있습니다. AI 처리 중에는 변경할 수 없습니다.","연산 장치 설정",this::modelSettings);settingItem(content,"휴대폰 AI Tip","휴대폰 회의 중 질문·어려운 용어에 짧은 도움을 제안합니다. 인식·저장은 별도로 계속되며 AI 분석은 최소10초 간격입니다.",null,null);Switch auto=new Switch(this);auto.setText("휴대폰 AI Tip 사용");auto.setTextColor(INK);auto.setChecked(getPreferences(0).getBoolean("phoneHelp",true));auto.setOnCheckedChangeListener((v,on)->getPreferences(0).edit().putBoolean("phoneHelp",on).apply());content.addView(auto);gap(content,14);settingItem(content,"문서 보기 · 글자 크기","회의록 전체 화면의 A− / A＋와 손가락 확대를 사용합니다. 저장 문서는 A4 양식으로 유지됩니다.","글자 크기 선택",()->new AlertDialog.Builder(this).setTitle("문서 글자 크기").setItems(new String[]{"작게","기본","크게","아주 크게"},(d,w)->{readingSize=new int[]{14,16,20,24}[w];getPreferences(0).edit().putInt("readingSize",readingSize).apply();toast("문서 글자 크기를 변경했습니다");}).show());settingItem(content,"회의 기록 · 삭제 · 공유","달력 날짜를 눌러 회의를 찾습니다. 카드 왼쪽 밀기 후 삭제 버튼, 오른쪽 밀기 후 공유 버튼을 누릅니다. 삭제한 원문·회의록은 복구할 수 없습니다.","회의록 기록 보기",this::archive);settingItem(content,"PDF · 문서 저장","회의록의 ‘양식 문서 저장’은 아이콘을 포함한 HTML입니다. ‘PDF · 인쇄’에서 PDF로 저장을 선택합니다. TXT는 원문과 회의록을 별도로 내보냅니다.",null,null);settingItem(content,"안경 자동 연결","휴대폰 마이크로만 회의할 때는 필요 없습니다. 안경을 사용할 때 서비스를 시작하고 MemoMind 폰 플러그인을 실행하세요.","안경 연결 시작",this::startConnection);settingItem(content,"연결 키 복구","자동 연결이 어려운 경우에만 연결 키를 복사합니다. 키를 아는 앱은 휴대폰 내부 서비스에 접근할 수 있습니다.","복구용 키 복사",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Memo 연결 키",AssistService.token(this)));toast("연결 키를 복사했습니다");});settingItem(content,"녹음·저장 안내","음성인식 언어는 한국어이며 기기 내 인식기를 사용합니다. 회의 원문은 자동 저장하고 원본 음성 파일은 저장하지 않습니다. 일시정지는 같은 회의에 이어 기록하며 완료 후 새 회의를 시작합니다.",null,null);settingItem(content,"서비스 중지","마이크와 안경 연결 서비스를 정지합니다. 저장된 회의 자료·AI 모델은 삭제하지 않습니다.","서비스 중지",()->{stopService(new Intent(this,AssistService.class));toast("서비스를 중지했습니다");});settingItem(content,"앱 정보","Memo 회의 0.16.0 · 로컬 AI 처리\n앱 삭제·데이터 초기화 시 내부 회의 자료와 모델이 사라질 수 있으므로 중요한 회의는 문서로 내보내세요.",null,null);}
 void kakaoSettings(LinearLayout content){KakaoMemory memory=KakaoMemory.get(this);settingItem(content,"카카오톡 AI 기억 · AI 폴더","카카오톡 알림의 텍스트만 기기 내부에 보관합니다. 오늘을 포함한 7일 자료에서 관련 원문 최대 3건을 AI Tip에 참고합니다. 사진·첨부파일·이전 대화 전체는 수집하지 않습니다. 날짜가 지난 자료는 수집·검색·설정 확인 시 자동 삭제합니다.\n"+memory.status()+"\n알림 접근: "+(((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).isNotificationListenerAccessGranted(new ComponentName(this,KakaoNotificationService.class))?"허용됨":"허용 필요"),"알림 접근 권한 설정",()->startActivity(new Intent(android.provider.Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));Switch collect=new Switch(this);collect.setText("카카오톡 수집 및 AI Tip 참고");collect.setTextColor(INK);collect.setChecked(memory.enabled());collect.setOnCheckedChangeListener((v,on)->{memory.enabled(on);toast(on?"알림 접근 권한도 허용해주세요":"수집·참고 중지 · 기존 자료는 보관기간까지 유지");});content.addView(collect);settingItem(content,"현재 알림 가져오기","알림창에 남아 있는 카카오톡 텍스트를 지금 가져옵니다. 최근 7일 자료만 저장하며 이미 수집한 알림은 중복 저장하지 않습니다. 지워진 알림과 과거 전체 대화는 가져올 수 없습니다.\n"+getSharedPreferences("kakao-memory",0).getString("lastImport","아직 가져오기 기록이 없습니다"),"현재 카카오톡 알림 가져오기",()->KakaoNotificationService.requestImport(this,message->{if(!isFinishing()&&!isDestroyed()){toast(message);if(settingsPage)settings();}}));settingItem(content,"AI 기억","저장된 최근 7일 카카오톡 알림에 대해 텍스트·음성으로 질문합니다. AI 답변과 날짜·대화방·발신 정보가 있는 검색 근거를 함께 확인할 수 있습니다.","AI 기억 열기",this::kakaoQuestion);settingItem(content,"일별 AI 정리","전날까지의 자료를 충전 중 유휴 시간에 조금씩 정리합니다. 음성 회의가 진행 중이면 연기합니다. AI Tip은 요약의 추측을 피하도록 관련 원문을 직접 참고합니다.","일별 정리 보기",()->new AlertDialog.Builder(this).setTitle("카카오톡 일별 AI 정리").setMessage(memory.summaryPreview()).setPositiveButton("확인",null).show());settingItem(content,"AI 기억 삭제","앱 내부 AI 폴더에 저장하며 다른 앱이나 서버에 업로드하지 않습니다. 알림이 숨겨졌거나 권한이 없으면 수집할 수 없습니다. 기존 자료 전체 삭제는 회의록과 AI 모델에 영향을 주지 않습니다.","저장된 카카오톡 자료 전체 삭제",()->new AlertDialog.Builder(this).setTitle("카카오톡 AI 기억 삭제").setMessage("저장된 알림 원문과 검색 색인을 모두 삭제할까요?").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{memory.clear();settings();}).show());gap(content,14);}
