  ScrollView scroll=new ScrollView(this);LinearLayout results=column();scroll.addView(results);TextView answer=text("궁금한 사람·대화방·주제를 입력해 주세요.",15,MUTED,false);answer.setTextIsSelectable(true);results.addView(answer);gap(results,14);LinearLayout sources=column();results.addView(sources);
  final KakaoVoice[] voice={null};final boolean[] answering={false};final long[] request={0};final boolean[] closed={false};Button ask=button("질문하기",true,()->{});ask.setOnClickListener(v->{if(voice[0]!=null&&voice[0].active())return;if(!memory.enabled()){answer.setText("설정에서 카카오톡 수집 및 AI Tip 참고를 켜주세요");sources.removeAllViews();return;}String query=question.getText().toString().trim();if(query.isEmpty()){question.setError("질문을 입력해 주세요");return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(question.getWindowToken(),0);long ticket=++request[0];long epoch=memory.generation(),day=KakaoMemory.cutoff();answering[0]=true;ask.setEnabled(false);answer.setTextColor(MUTED);answer.setText("관련 알림을 찾고 있습니다…");sources.removeAllViews();new Thread(()->{boolean locked=false;List<KakaoMemory.Evidence> evidence=Collections.emptyList();String shown;try{if(!memory.enabled())throw new IllegalStateException("설정에서 카카오톡 수집 및 AI Tip 참고를 켜주세요");evidence=memory.find(query);if(evidence.isEmpty())shown="저장된 알림에서 관련 내용을 찾지 못했습니다. 사람·대화방·주제 이름으로 다시 질문해 주세요.";else{locked=MeetingManager.AI_LOCK.tryLock();if(!locked)throw new IllegalStateException("다른 AI 작업이 진행 중입니다. 잠시 후 다시 질문해 주세요");MeetingManager manager=MeetingManager.get(this);if(!manager.hasModel())throw new IllegalStateException("설정에서 로컬 AI 모델을 등록·선택해 주세요");KakaoAnswer.Answer result=KakaoAnswer.generate(manager.engine(),query,evidence);StringBuilder refs=new StringBuilder();for(int id:result.references)refs.append(" [").append(id).append(']');shown=result.text+(refs.length()>0?"\n\n답변 참고 알림"+refs:"");}}catch(Exception|LinkageError e){shown=e.getMessage()==null?"AI 답변을 만들지 못했습니다. 다시 시도해 주세요.":e.getMessage();}finally{if(locked)MeetingManager.AI_LOCK.unlock();}String output=shown;List<KakaoMemory.Evidence> found=evidence;runOnUiThread(()->{if(closed[0]||!dialog.isShowing()||ticket!=request[0]||isFinishing()||isDestroyed())return;answering[0]=false;ask.setEnabled(true);if(epoch!=memory.generation()||day!=KakaoMemory.cutoff()||!memory.enabled()){answer.setText("AI 기억 설정 또는 보관기간이 변경되었습니다. 다시 질문해 주세요.");sources.removeAllViews();return;}answer.setTextColor(INK);answer.setText(output);if(!found.isEmpty()){sources.addView(text("검색된 알림 · "+found.size()+"건 기준",13,MUTED,true));gap(sources,10);for(int i=0;i<found.size();i++){KakaoMemory.Evidence item=found.get(i);LinearLayout card=column();card.setPadding(dp(14),dp(14),dp(14),dp(14));card.setBackground(shape(WHITE,16));card.addView(text("["+(i+1)+"] "+date(item.at,"yyyy.MM.dd HH:mm"),12,MUTED,true));gap(card,7);card.addView(text("제목·대화방: "+item.room+(item.sender.isEmpty()?"":"\n발신: "+item.sender),13,INK,true));gap(card,8);TextView original=text(item.text,14,INK,false);original.setTextIsSelectable(true);card.addView(original);sources.addView(card);gap(sources,10);}sources.addView(text("알림 기준 AI 답변입니다. 중요한 내용은 원문과 최신 대화를 확인해 주세요.",12,MUTED,false));}scroll.smoothScrollTo(0,0);});},"kakao-memory-question").start();});TextView voiceStatus=text("한국어 음성으로 질문을 입력할 수 있습니다.",12,MUTED,false);Button mic=button("음성 질문",false,()->{});voice[0]=new KakaoVoice(this,new KakaoVoice.Callback(){public void text(String value){if(!closed[0]&&dialog.isShowing()){question.setText(value);question.setSelection(question.length());}}public void state(boolean listening,String message){if(closed[0]||!dialog.isShowing())return;voiceStatus.setText(message);mic.setText(listening?"말하기 완료":"음성 질문");ask.setEnabled(!listening&&!answering[0]);}});activeQuestionVoice=voice[0];Runnable beginVoice=()->{if(closed[0]||!dialog.isShowing()||answering[0])return;try{AssistService service=AssistService.current;if(service!=null){JSONObject live=service.phoneSnapshot();if(live.optBoolean("running")||live.optBoolean("phoneRecording")){voiceStatus.setText("회의를 일시정지한 뒤 음성 질문을 사용해주세요.");return;}}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(question.getWindowToken(),0);voice[0].start();}catch(Exception e){voiceStatus.setText("마이크 상태를 확인하지 못했습니다. 잠시 후 다시 시도해주세요.");}};mic.setOnClickListener(v->{if(answering[0])return;if(voice[0].active()){voice[0].stop();return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=0){pendingKakaoVoice=beginVoice;voiceStatus.setText("음성 질문을 위해 마이크 권한을 허용해주세요.");requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},23);return;}beginVoice.run();});LinearLayout inputActions=new LinearLayout(this);inputActions.addView(mic,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams askLp=new LinearLayout.LayoutParams(0,dp(48),1);askLp.leftMargin=dp(8);inputActions.addView(ask,askLp);page.addView(inputActions);gap(page,8);page.addView(voiceStatus);gap(page,16);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setOnDismissListener(d->{closed[0]=true;request[0]++;pendingKakaoVoice=null;voice[0].close();if(activeQuestionVoice==voice[0])activeQuestionVoice=null;});dialog.show();Window window=dialog.getWindow();if(window!=null){window.setLayout(-1,-1);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);window.setStatusBarColor(BG);window.setNavigationBarColor(BG);window.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}page.requestApplyInsets();return dialog;
