 void phoneHelp(JSONObject snapshot,String context){if(!getPreferences(0).getBoolean("phoneHelp",true)||phoneHelping||context.trim().length()<2||context.equals(phoneHelpContext)||SystemClock.elapsedRealtime()-phoneHelpAt<10000)return;String session=snapshot.optString("session");if(!session.equals(phoneHelpSession)){phoneHelpSession=session;phoneTopics.clear();}final long memoryEpoch=KakaoMemory.get(this).generation();final long generation=phoneHelpGeneration;phoneHelping=true;phoneHelpAt=SystemClock.elapsedRealtime();phoneHelpContext=context;Set<String> ids=new HashSet<>();JSONArray before=snapshot.optJSONArray("finals");if(before!=null)for(int i=0;i<before.length();i++)ids.add(before.optJSONObject(i).optString("id"));new Thread(()->{boolean locked=MeetingManager.AI_LOCK.tryLock();try{if(!locked)return;String raw=MeetingManager.get(this).engine().explain(KakaoMemory.get(this).augment(context.substring(Math.max(0,context.length()-500))),"자동 대화 도움","assist");org.json.JSONObject help=new JSONObject(raw.substring(raw.indexOf('{'),raw.lastIndexOf('}')+1));String kind=help.optString("kind"),topic=help.optString("topic"),text=help.optString("text");if(!(kind.equals("reply")||kind.equals("term"))||topic.isEmpty()||text.isEmpty())return;runOnUiThread(()->{try{if(memoryEpoch!=KakaoMemory.get(this).generation()||generation!=phoneHelpGeneration||!phonePage||AssistService.current==null||!getPreferences(0).getBoolean("phoneHelp",true))return;JSONObject now=AssistService.current.phoneSnapshot();if(!now.optString("session").equals(session)||!now.optBoolean("phoneRecording"))return;JSONArray finals=now.optJSONArray("finals");int count=0;if(finals!=null)for(int i=0;i<finals.length();i++)if(!ids.contains(finals.optJSONObject(i).optString("id")))count++;if(count>=10||phoneTopics.contains(topic))return;phoneTopics.add(topic);String shown=text;if(kind.equals("term")){String known=Glossary.exact(topic);if(known!=null)shown=known;}phoneTip.setTextColor(INK);phoneTip.setText((kind.equals("reply")?"답변 도움 · ":"용어 · ")+topic+"\n"+shown);}catch(Exception ignored){}});}catch(Exception|LinkageError e){runOnUiThread(()->{if(generation==phoneHelpGeneration&&phonePage&&phoneTip!=null){phoneTip.setTextColor(MUTED);phoneTip.setText("AI 도움 대기 · "+e.getMessage());}});}finally{if(locked)MeetingManager.AI_LOCK.unlock();phoneHelping=false;}},"phone-ai-tip").start();}
 void modelSettings(){MeetingManager manager=MeetingManager.get(this);String[] actions={"모델 파일 등록 (.litertlm / .gguf)","사용할 모델 선택","선택 모델 응답 테스트","GGUF 연산 장치 · CPU / GPU"};new AlertDialog.Builder(this).setTitle("AI 모델 · "+manager.modelName()).setItems(actions,(dialog,item)->{if(item==0){if(copying){toast("모델을 가져오는 중입니다");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);}else if(item==1){String[] labels={"LiteRT-LM · "+(manager.modelFile("litertlm").isFile()?"등록됨":"미등록"),"GGUF · "+(manager.modelFile("gguf").isFile()?"등록됨":"미등록")};new AlertDialog.Builder(this).setTitle("사용할 AI 모델").setSingleChoiceItems(labels,manager.selectedModel().equals("gguf")?1:0,(pick,index)->{pick.dismiss();new Thread(()->{try{manager.selectModel(index==1?"gguf":"litertlm");runOnUiThread(()->toast("선택됨: "+manager.modelName()));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}},"model-switch").start();}).setNegativeButton("닫기",null).show();}else if(item==2)testModel();else new AlertDialog.Builder(this).setTitle("GGUF 연산 장치").setSingleChoiceItems(new String[]{"CPU · 기본","GPU · OpenCL / Adreno"},manager.ggufBackend().equals("opencl")?1:0,(pick,index)->{pick.dismiss();new Thread(()->{try{manager.selectBackend(index==1?"opencl":"cpu");runOnUiThread(()->toast("GGUF 연산 장치를 변경했습니다"));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}},"backend-select").start();}).setNegativeButton("닫기",null).show();}).setNegativeButton("닫기",null).show();}
 void testModel(){toast("선택 모델을 불러와 응답을 테스트합니다");new Thread(()->{MeetingManager m=MeetingManager.get(this);if(!MeetingManager.AI_LOCK.tryLock()){runOnUiThread(()->toast("AI 처리 완료 후 테스트하세요"));return;}try{long start=SystemClock.elapsedRealtime();AiEngine ai=m.engine();long loaded=SystemClock.elapsedRealtime();String name=m.modelName()+(m.selectedModel().equals("gguf")?" / "+m.ggufBackend():"");String result=ai.explain("역광 촬영에서 HDR 기술의 의미와 효과를 검토하고 있습니다.","자동 대화 도움","assist");long end=SystemClock.elapsedRealtime();String report="모델: "+name+"\n준비: "+(loaded-start)+"ms\n생성: "+(end-loaded)+"ms\n\n"+result;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("AI 모델 테스트 결과").setMessage(report).setPositiveButton("확인",null).show());}catch(Exception|LinkageError e){runOnUiThread(()->toast("모델 테스트 실패: "+e.getMessage()));}finally{MeetingManager.AI_LOCK.unlock();}},"model-test").start();}
 void completeMeeting(){new Thread(()->{try{if(AssistService.running){java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("http://127.0.0.1:18772/meeting/complete").openConnection();c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+AssistService.token(this));c.setConnectTimeout(3000);c.setReadTimeout(15000);int code=c.getResponseCode();c.disconnect();if(code!=200)throw new IOException("회의 완료 실패 HTTP "+code);}else MeetingManager.get(this).complete();runOnUiThread(()->{resetPhoneMeetingDisplay();toast("원문 저장 완료 · 회의록을 만들고 있습니다");lastList="";refresh();});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}},"meeting-complete").start();}
 void export(String id,String kind){final String styled=kind.equals("html")?minutesHtml():null;new Thread(()->{try{File file;if(kind.equals("html")){file=new File(getCacheDir(),"meeting-document.html");MeetingStore.atomic(file,styled);}else file=MeetingManager.get(this).document(id,kind);runOnUiThread(()->{exportFile=file;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(kind.equals("html")?"text/html":"text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,(kind.equals("transcript")?"회의원문-":"회의록-")+id.substring(0,8)+(kind.equals("html")?".html":".txt"));startActivityForResult(i,30);});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}},"meeting-export").start();}
 void toast(String text){Toast.makeText(this,text==null?"다시 시도해 주세요":text,Toast.LENGTH_LONG).show();}
 @Override protected void onResume(){super.onResume();new Thread(()->KakaoMemory.get(this).prune(),"memory-retention").start();if(AssistService.running)AssistService.PAIRING.open(System.currentTimeMillis());if(settingsPage)settings();handler.removeCallbacks(tick);handler.post(tick);}
 @Override protected void onPause(){handler.removeCallbacks(tick);if(activeQuestionVoice!=null&&activeQuestionVoice.active()){activeQuestionVoice.close();}super.onPause();}
 @Override protected void onDestroy(){pendingKakaoVoice=null;if(activeQuestionVoice!=null){activeQuestionVoice.close();activeQuestionVoice=null;}super.onDestroy();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==23){Runnable pending=pendingKakaoVoice;pendingKakaoVoice=null;if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&pending!=null)pending.run();else toast("마이크 권한을 허용하면 음성 질문을 사용할 수 있습니다");}}
 @Override public void onBackPressed(){if(detailId!=null)archive();else if(currentTab!=0)navigate(0);else super.onBackPressed();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==30&&exportFile!=null){File file=exportFile;new Thread(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);runOnUiThread(()->toast("TXT를 저장했습니다"));}catch(Exception e){runOnUiThread(()->toast("저장 실패: "+e.getMessage()));}},"meeting-export").start();return;}if(request!=10||copying)return;copying=true;toast("모델 등록 중 · 기존 두 형식은 별도로 유지됩니다");android.net.Uri uri=data.getData();new Thread(()->{File tmp=new File(getFilesDir(),"model-import.tmp");try{String name="가져온 AI 모델";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}String kind;long total=8;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(tmp)){byte[] magic=new byte[8];new DataInputStream(in).readFully(magic);kind=ModelFormat.detect(magic);out.write(magic);byte[] buffer=new byte[1048576];int n;while((n=in.read(buffer))!=-1){total+=n;if(total>5L*1024*1024*1024)throw new IOException("모델이 너무 큽니다 (최대 5GB)");out.write(buffer,0,n);}}if(total<1000000)throw new IOException("불완전한 모델 파일입니다");MeetingManager.get(this).installModel(tmp,kind,name);String format=kind;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("모델 등록 완료").setMessage(format+" 모델을 등록했습니다. '사용할 모델 선택'에서 변경 후 응답 테스트를 실행하세요.").setPositiveButton("확인",null).show());}catch(Exception|LinkageError e){tmp.delete();runOnUiThread(()->toast("등록 실패: "+e.getMessage()));}finally{copying=false;}},"model-import").start();}
